repeat_checks={'physical_input':repeat['physical_microphone_used'] and not repeat['synthetic'],'privacy_no_text':all('text'not in v and 'embedding'not in v for v in rr),'unique_binding':len(set(v['segment_id']for v in rr))==len(rr)and all(v['wrong_segment_events']==0 for v in rr),'no_backing_turns':all(v['unexpected_turns']==0 for v in rr),'no_queue_loss':not repeat['errors']and repeat['dropped_voices']==0,'missing_transcripts_retained':sum(v['status']=='no_transcript'for v in rr)==4,'speech_failures_retained':sum(v['output_nonzero_samples']>0 or v['assistant_text_chars']>0 for v in rr)==3}
