report={'ok':all(x['evidence_valid']for x in cases) and real_summary['evidence_valid'] and repeat_summary['evidence_valid'],'cases':cases,'real_microphone':real_summary,'real_microphone_repeat':repeat_summary,'conclusion':'Per-segment identity binding works in this fixture; prompt-only silent ASR failed in both runs; quiescence is provisional, not a server completion guarantee','live_runs_repeated':False,'adoption':'reject per-segment new-connection design: user found responsiveness impractical; prototype unchanged'}
